#include <algorithm>
#include <cmath>

class Solution {
public:
    double angleClock(int hour, int minutes) {
        double hAngle = (hour % 12) * 30.0 + minutes * 0.5;
        double mAngle = minutes * 6.0;
        double diff = std::abs(hAngle - mAngle);
        return std::min(diff, 360.0 - diff);
    }
};

class Solution {
    public double angleClock(int hour, int minutes) {
        double hAngle = (hour % 12) * 30.0 + minutes * 0.5;
        double mAngle = minutes * 6.0;
        double diff = Math.abs(hAngle - mAngle);
        return Math.min(diff, 360.0 - diff);
    }
}

var angleClock = function(hour, minutes) {
    const hAngle = (hour % 12) * 30 + minutes * 0.5;
    const mAngle = minutes * 6;
    const diff = Math.abs(hAngle - mAngle);
    return Math.min(diff, 360 - diff);
};
